      check(['toggle-filters','select-cards','find-memberships'].every(id=>{const b=doc.getElementById(id);return b.querySelector('svg')&&b.getAttribute('aria-label')&&b.dataset.tooltip;}),'Native research tools use labeled SVG icons with hover text');doc.getElementById('select-cards').click();await wait(()=>doc.getElementById('select-cards').getAttribute('aria-pressed')==='true','Native box selection enabled');check(!doc.getElementById('selection-hint-overlay').hidden&&canvas.getComputedStyle(viewport).cursor==='crosshair','Native box selection exposes crosshair and drag hint');doc.getElementById('select-cards').dispatchEvent(new canvas.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));check(doc.getElementById('selection-hint-overlay').hidden&&doc.getElementById('select-cards').getAttribute('aria-pressed')==='false','Native Escape ends selection mode');
      await canvas.CanvasApp.createBoard('Native canvas objects');check(doc.querySelectorAll('#object-toolbar button').length===8,'Native object palette exposes shapes, sticky notes, text, tables, wireframes, templates and library');
      canvas.CanvasApp.placeObject({type:'sticky',colour:'#f8d6df'},{x:100,y:100});canvas.CanvasApp.placeObject({type:'text'},{x:400,y:100});canvas.CanvasApp.placeObject({type:'shape',shape:'diamond'},{x:750,y:100});canvas.CanvasApp.placeObject({type:'table',rows:3,cols:3},{x:100,y:400});canvas.CanvasApp.placeObject({type:'wireframe',variant:'phone'},{x:800,y:400});const libraryPreset=canvas.CanvasObjectPresets[0];canvas.CanvasApp.placeObject({type:'library',item:libraryPreset},{x:1200,y:100});await canvas.CanvasApp.flush();
      check(canvas.CanvasApp.getBoard().nodes.length===6&&doc.querySelectorAll('.object-card').length===6,'Native object types insert and save as canvas objects');
